/**
 * Renders src/design/tokens.css from tokens.js + motion.js, so the CSS custom properties can
 * never drift from the JS tokens: `npm run tokens` writes the file (writeTokensCss.mjs) and
 * tokens.test.js fails when the committed file differs from `renderTokensCss()`.
 */
import { cssVariables } from "./tokens.js";
import { motionCssVariables } from "./motion.js";

export const TOKENS_CSS_HEADER = `/*
 * GENERATED by src/design/writeTokensCss.mjs from src/design/tokens.js + motion.js.
 * Do not edit by hand: change tokens.js, then run \`npm run tokens\`.
 * (tokens.test.js fails when this file is out of sync.)
 */`;

/** The full text of tokens.css (LF line endings, trailing newline). */
export function renderTokensCss() {
  const lines = [...cssVariables(), ...motionCssVariables()].map(([name, value]) => `  ${name}: ${value};`);
  return `${TOKENS_CSS_HEADER}\n:root {\n${lines.join("\n")}\n}\n`;
}
